1	package world
2	
3	import (
4		"errors"
5		"os"
6		"syscall"
7	)
8	
9	// Record 是一次成功保存留下的、可供读取的记录。
10	type Record struct {
11		// ID 是记录标识。
12		ID RecordID
13		// Parent 是父记录标识；槽首条记录为空。
14		Parent RecordID
15		// SlotFirst 表示这是其所在槽的首条记录。
16		SlotFirst bool
17		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
18		State State
19	}
20	
21	func acquireSharedLock(dir string) (*fileLock, error) {
22		path := dir + "/lock"
23		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
24		if err != nil {
25			return nil, err
26		}
27		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
28			f.Close()
29			return nil, err
30		}
31		return &fileLock{f: f}, nil
32	}
33	
34	// loadAndVerifyLocked 读取记录文件，校验其内容校验和（校验和已包含
35	// 父记录关系）、父记录是否存在，以及世界数据是否自洽。
36	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
37		env, err := loadRecord(recordPath(a.dir, id))
