			lastReason = (&VersionRejectedError{
				Record:  id,
				Version: env.State.Rules.Version,
			}).Error()
			continue
		}
		return env, nil
	}

	if lastReason == "" {
		lastReason = "槽中没有任何可确认归属的历史记录"
