		if _, ok := parent[x]; !ok {
			parent[x] = x
		}
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	union := func(a, b string) bool {
		ra, rb := find(a), find(b)
		if ra == rb {
			return false
		}
		parent[ra] = rb
		return true
	}

	picked := make(map[edgeKey]struct{}, target)
	components := 0
	for key := range required {
		picked[key] = struct{}{}
		if union(key.a, key.b) {
			components--
		}
	}
