	for _, l := range allLocations(pool) {
		if _, ok := parent[l]; !ok {
			parent[l] = l
			components++
		}
	}
	// 先沿打乱次序连通全图。
	for _, key := range pool {
		if components == 1 {
			break
		}
		if _, ok := picked[key]; ok {
			continue
		}
		if union(key.a, key.b) {
			picked[key] = struct{}{}
			components--
		}
	}
	// 再补足到目标数量。
	for _, key := range pool {
		if len(picked) >= target {
			break
		}
		if _, ok := picked[key]; ok {
			continue
		}
		picked[key] = struct{}{}
	}
	return picked
}

// allLocations 返回可用道路中出现的全部地点（已按字典序）。
func allLocations(pool []edgeKey) []string {
	seen := make(map[string]struct{})
	for _, e := range pool {
		seen[e.a] = struct{}{}
		seen[e.b] = struct{}{}
	}
	out := make([]string, 0, len(seen))
	for l := range seen {
		out = append(out, l)
	}
	sort.Strings(out)
	return out
}

// mapRNG 是种子驱动的确定性伪随机数生成器（splitmix64）。自包含实现，
// 不依赖 math/rand 的版本行为，因此同一种子在任何进程、任何 Go 版本下
// 都给出完全一致的序列。
type mapRNG struct {
	state uint64
}

func newMapRNG(seed int64) *mapRNG {
