		pool[i], pool[j] = pool[j], pool[i]
	}

	parent := make(map[string]string, len(pool)+1)
	for key := range required {
		parent[key.a] = key.a
		parent[key.b] = key.b
	}
	find := func(x string) string {
		// 地点可能尚未出现在 parent 中（没有任何必有道路经过），惰性建立。
		if _, ok := parent[x]; !ok {
