			return false
		}
		parent[ra] = rb
		return true
	}

	picked := make(map[edgeKey]struct{}, target)
	components := 0
	for key := range required {
		picked[key] = struct{}{}
		if union(key.a, key.b) {
			components--
		}
	}
	// 没有必有道路经过的地点各自是一个连通分量。
