	for _, key := range pool {
		if len(picked) >= target {
			break
		}
		if _, ok := picked[key]; ok {
			continue
		}
		picked[key] = struct{}{}
	}
	return picked
}

// allLocations 返回可用道路中出现的全部地点（已按字典序）。
func allLocations(pool []edgeKey) []string {
	seen := make(map[string]struct{})
	for _, e := range pool {
		seen[e.a] = struct{}{}
		seen[e.b] = struct{}{}
	}
	out := make([]string, 0, len(seen))
	for l := range seen {
		out = append(out, l)
	}
	sort.Strings(out)
	return out
}

